rows = list(csv.DictReader(open(os.path.join(ROOT, "docs/discovery/feature-matrix.tsv")), delimiter="\t"))
by = collections.OrderedDict()
for r in rows: by.setdefault(r["area"], []).append(r)
count = collections.Counter(S.get(r["id"], (M,))[0] for r in rows) + collections.Counter(u[3] for u in UPG)
esc = lambda s: (s or "").replace("|", "\\|").replace("\n", " ")
out = ["# Feature parity and implementation status", "",
 "Generated by `tools/gen_feature_parity.py` from the discovery matrix (`docs/discovery/feature-matrix.tsv`, 167 rows, PV\\*SOL premium 2026 R4–R8 and 2027 R1) plus the SolarCraft upgrades and platform rows. Edit the status table in the script and regenerate; do not edit this file by hand.", "",
 "**Status values.** *working*: the workflow is implemented end to end and covered by the named test. *partial*: part of the user task works; the gap is stated. *missing*: not implemented. *blocked*: needs an owner decision, paid data or proprietary material. *unverified*: built but not observed on the target (hardware, receiving application).", "",
 "**References.** Each row cites its private evidence key (`EV-<id>`) in the reference column. The key resolves to exact paths and sections inside the private reference bundle through the private evidence index, which stays out of this public repository (owner decision D-08). A page, button or planned feature is not counted as implemented.", "",
 "| Status | Rows |", "|---|---:|"] + [f"| {k} | {count[k]} |" for k in (W, P, M, B, U)] + [""]
for area, rs in by.items():
    out += [f"## {area}", "", "| ID | Feature | Reference | User task and expected behaviour | Current implementation (code, observed) | Acceptance test | Status |", "|---|---|---|---|---|---|---|"]
    for r in rs:
        st, impl, test = S.get(r["id"], (M, "—", "—"))
        out.append(f"| {r['id']} | {esc(r['feature'])} | {esc(r['evidence'])}; EV-{r['id']} ({r['baseline_version']}) | {esc(r['user_job'])}. Expected: {esc(r['acceptance_test'])} | {esc(impl)} | {esc(test)} | **{st}** |")
    out.append("")
out += ["## SolarCraft upgrades and platforms", "", "| ID | Source | User task | Current implementation | Acceptance test | Status |", "|---|---|---|---|---|---|"]
for u in UPG: out.append(f"| {u[0]} | {u[1]} | {esc(u[2])} | {esc(u[4])} | {esc(u[5])} | **{u[3]}** |")
open(os.path.join(ROOT, "docs/feature-parity.md"), "w").write("\n".join(out) + "\n")
print(dict(count))
